const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];

const x = new Int32Array(N + 1);
const y = new Int32Array(N + 1);
let pos = 1;
for (let i = 1; i <= N; i++) {
    x[i] = data[pos++];
    y[i] = data[pos++];
}

const M = 4194304;
const E = N * N;
const keys = new Float64Array(E);

let idx = 0;
for (let v = 1; v <= N; v++) {
    const xv = x[v];
    const yv = y[v];
    const base = (v - 1) * 2048;
    for (let u = 0; u <= N; u++) {
        if (u === v) continue;
        const dx = x[u] - xv;
        const dy = y[u] - yv;
        const dist = dx * dx + dy * dy;
        keys[idx++] = dist * M + base + u;
    }
}

keys.sort();

const best = new Int32Array(N + 1);
const groupBest = new Int32Array(N + 1);
const touched = new Int32Array(N + 1);

let ans = 0;
let i = E - 1;

while (i >= 0) {
    const w = Math.floor(keys[i] / M);
    const minKey = w * M;
    let tptr = 0;

    while (i >= 0 && keys[i] >= minKey) {
        const code = keys[i] - minKey;
        const v = (code >>> 11) + 1;
        const u = code & 2047;

        let dp = 0;
        if (u === 0) {
            dp = 1;
        } else {
            const prev = best[u];
            if (prev > 0) dp = prev + 1;
        }

        if (dp > 0) {
            if (dp > groupBest[v]) {
                if (groupBest[v] === 0) touched[tptr++] = v;
                groupBest[v] = dp;
            }
            if (dp > ans) ans = dp;
        }

        i--;
    }

    for (let t = 0; t < tptr; t++) {
        const v = touched[t];
        const gb = groupBest[v];
        if (gb > best[v]) best[v] = gb;
        groupBest[v] = 0;
    }
}

console.log(ans);
